133	            owners = this.clinicService.findAllOwners();
134	        }
135	        if (owners.isEmpty()) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        owners.forEach(this::populateHouseholdSize);
139	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
140	    }
