155	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
156	        List<String> missingFields = new ArrayList<>();
157	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
158	            missingFields.add("firstName");
159	        }
160	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
161	            missingFields.add("lastName");
162	        }
163	        // Normalize the address up front; the required-field check rejects it when it is blank
164	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
165	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
166	        if (!StringUtils.hasText(normalizedAddress)) {
167	            missingFields.add("address");
168	        }
169	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
170	            missingFields.add("city");
171	        }
172	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
173	            missingFields.add("telephone");
174	        }
175	        if (!missingFields.isEmpty()) {
176	            throw new InvalidRequestException(missingFields);
177	        }
178	        HttpHeaders headers = new HttpHeaders();
179	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
180	        // Store (and later return) the normalized address computed above.
181	        owner.setAddress(normalizedAddress);
182	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
183	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
184	        owner.setTelephone(normalizedTelephone);
185	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
186	        owner.setEmail(normalizeEmail(owner.getEmail()));
187	        // Default the (optional) registration date to the server's current date when none was supplied.
188	        if (owner.getRegistrationDate() == null) {
189	            owner.setRegistrationDate(LocalDate.now());
190	        }
191	        // The effective registration date must fall on a business day: when it lands on a Saturday or
192	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
193	        // derived from the registration date below (daily create-limit, membership number) uses this
194	        // adjusted date.
195	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
196	        // Reject the request once the maximum number of owners for the owner's registration day has
197	        // been reached (100 or more owners already created on that date).
198	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
199	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
200	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
201	        }
202	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
203	        // owner's registration day at the moment this owner was created; otherwise clear it.
204	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
205	        // Reject the request when the owner's city has already reached its owner capacity.
206	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
207	            throw new CityCapacityException(owner.getCity());
208	        }
209	        // Reject the request if the E.164 telephone is already used by another owner.
210	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
211	            throw new DuplicateTelephoneException(normalizedTelephone);
212	        }
213	        // Reject the request if another owner already shares the same last name and address
214	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
215	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
216	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
217	        // every existing member that does not yet carry it.
218	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
219	        if (!householdMembers.isEmpty()) {
220	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
221	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
222	            }
223	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
224	            owner.setHouseholdId(householdId);
225	            for (Owner member : householdMembers) {
226	                if (!householdId.equals(member.getHouseholdId())) {
227	                    member.setHouseholdId(householdId);
228	                    this.clinicService.saveOwner(member);
229	                }
230	            }
231	        }
232	        // Record how many existing owners already share this first name and last name
233	        // (compared case-insensitively) before this owner is created.
234	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
235	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
236	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
237	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
238	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
239	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
240	        this.clinicService.saveOwner(owner);
241	        populateHouseholdSize(owner);
242	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
243	        // Emit an audit line carrying the new owner's id, customer code, registration date
244	        // and numeric membership level.
245	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
246	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
247	            ownerDto.getMembershipLevel());
248	        headers.setLocation(UriComponentsBuilder.newInstance()
249	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
250	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
256	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
257	        if (currentOwner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        currentOwner.setAddress(ownerFieldsDto.getAddress());
261	        currentOwner.setCity(ownerFieldsDto.getCity());
262	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
263	        currentOwner.setLastName(ownerFieldsDto.getLastName());
264	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
265	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
266	        this.clinicService.saveOwner(currentOwner);
267	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
268	    }
269	
270	    /**
271	     * Populate the owner's household size: the number of owners sharing this owner's
272	     * {@code householdId} (including the owner itself). An owner with no household is a household
273	     * of one.
274	     *
275	     * @param owner the owner whose household size should be computed and set
276	     */
277	    private void populateHouseholdSize(Owner owner) {
278	        String householdId = owner.getHouseholdId();
279	        if (!StringUtils.hasText(householdId)) {
280	            owner.setHouseholdSize(1);
281	            return;
282	        }
283	        int size = (int) this.clinicService.findAllOwners().stream()
284	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
285	            .count();
286	        owner.setHouseholdSize(size);
287	    }
288	
289	    /**
290	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
291	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
292	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
293	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
294	     *
295	     * @param city     the owner's city
296	     * @param lastName the owner's last name
297	     * @return the generated customer code
298	     */
299	    private String generateCustomerCode(String city, String lastName) {
300	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
301	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
302	        String normalizedCity = normalizeForComparison(city);
303	        int sequence = (int) this.clinicService.findAllOwners().stream()
304	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
305	            .count() + 1;
306	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
307	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
308	    }
309	
310	    /**
311	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
312	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
313	     * that is stored, returned and used for every value derived from it.
314	     *
315	     * @param date the effective registration date (supplied or defaulted)
316	     * @return the same date when it is a weekday, otherwise the next Monday
317	     */
318	    private LocalDate rollToBusinessDay(LocalDate date) {
319	        DayOfWeek dayOfWeek = date.getDayOfWeek();
320	        if (dayOfWeek == DayOfWeek.SATURDAY) {
321	            return date.plusDays(2);
322	        }
323	        if (dayOfWeek == DayOfWeek.SUNDAY) {
324	            return date.plusDays(1);
325	        }
326	        return date;
327	    }
328	
329	    /**
330	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
331	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
332	     *
333	     * @param customerCode     the owner's already-assigned customer code
334	     * @param registrationDate the owner's registration date
335	     * @return the generated membership number
336	     */
337	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
338	        String yy = String.format("%02d", registrationDate.getYear() % 100);
339	        return String.format("%s-M%s", customerCode, yy);
340	    }
341	
342	    /**
343	     * Count the existing owners that share the given first name and last name, comparing each
344	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
345	     * yet persisted, so it is not included in the count.
346	     *
347	     * @param firstName the incoming owner's first name
348	     * @param lastName  the incoming owner's last name
349	     * @return the number of existing namesakes
350	     */
351	    private int countNamesakes(String firstName, String lastName) {
352	        String normalizedFirstName = normalizeForComparison(firstName);
353	        String normalizedLastName = normalizeForComparison(lastName);
354	        return (int) this.clinicService.findAllOwners().stream()
355	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
356	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
357	            .count();
358	    }
359	
360	    /**
361	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
362	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
363	     *
364	     * @param city the incoming owner's city
365	     * @return the number of existing owners already in that city
366	     */
367	    private int countOwnersInCity(String city) {
368	        String normalizedCity = normalizeForComparison(city);
369	        return (int) this.clinicService.findAllOwners().stream()
370	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
371	            .count();
372	    }
373	
374	    /**
375	     * Count the existing owners whose registration date equals the given date. The incoming owner is
376	     * not yet persisted, so it is not included in the count.
377	     *
378	     * @param registrationDate the incoming owner's registration date
379	     * @return the number of existing owners already registered on that date
380	     */
381	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
382	        return (int) this.clinicService.findAllOwners().stream()
383	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
384	            .count();
385	    }
386	
387	    /**
388	     * Find the existing owners that live in the same household as the given values, i.e. those that
389	     * share both the last name and the address when each is compared case-insensitively with
390	     * collapsed whitespace.
391	     *
392	     * @param lastName the incoming owner's last name
393	     * @param address  the incoming owner's address
394	     * @return the matching existing owners (possibly empty)
395	     */
396	    private List<Owner> findHouseholdMembers(String lastName, String address) {
397	        String normalizedLastName = normalizeForComparison(lastName);
398	        String normalizedAddress = normalizeForComparison(address);
399	        return this.clinicService.findAllOwners().stream()
400	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
401	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
402	            .toList();
403	    }
404	
405	    /**
406	     * Generate a stable shared household identifier for the given last name and address. The value is
407	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
408	     * and address, so every owner joining the same household resolves to the same identifier. It is the
409	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
410	     *
411	     * @param lastName the household's last name
412	     * @param address  the household's address
413	     * @return the stable household identifier
414	     */
415	    private String generateHouseholdId(String lastName, String address) {
416	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
417	        try {
418	            byte[] digest = MessageDigest.getInstance("SHA-256")
419	                .digest(key.getBytes(StandardCharsets.UTF_8));
420	            StringBuilder sb = new StringBuilder(digest.length * 2);
421	            for (byte b : digest) {
422	                sb.append(String.format("%02x", b));
423	            }
424	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
425	        } catch (java.security.NoSuchAlgorithmException e) {
426	            throw new IllegalStateException("SHA-256 not available", e);
427	        }
428	    }
429	
430	    /**
431	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
432	     * single space, upper-case the result and expand common street-type abbreviations token by token
433	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
434	     * to the empty string. The result is the canonical form that is stored, returned and used for every
435	     * address comparison (household duplicate detection and the shared household id).
436	     *
437	     * @param address the raw address, may be {@code null}
438	     * @return the normalized address
439	     */
440	    private String normalizeAddress(String address) {
441	        if (address == null) {
442	            return "";
443	        }
444	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
445	        if (collapsed.isEmpty()) {
446	            return "";
447	        }
448	        String[] tokens = collapsed.split(" ");
449	        StringBuilder sb = new StringBuilder(collapsed.length());
450	        for (int i = 0; i < tokens.length; i++) {
451	            if (i > 0) {
452	                sb.append(' ');
453	            }
454	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
455	        }
456	        return sb.toString();
457	    }
458	
459	    /**
460	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
461	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
462	     *
463	     * @param value the raw value, may be {@code null}
464	     * @return the normalized value
465	     */
466	    private String normalizeForComparison(String value) {
467	        if (value == null) {
468	            return "";
469	        }
470	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
471	    }
472	
473	    /**
474	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
475	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
476	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
477	     * is returned lower-cased.
478	     *
479	     * @param email the raw email from the request payload, may be {@code null}
480	     * @return the lower-cased email, or {@code null} when none was provided
481	     */
482	    private String normalizeEmail(String email) {
483	        if (!StringUtils.hasText(email)) {
484	            return null;
485	        }
486	        if (!EMAIL_PATTERN.matcher(email).matches()) {
487	            throw new InvalidRequestException(List.of("email"));
488	        }
489	        return email.toLowerCase(Locale.ROOT);
490	    }
491	
492	    /**
493	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
494	     * already carries a leading '+' keeps its country code; otherwise the default country code
495	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
496	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
497	     * is thrown (mapped to 400 Bad Request).
498	     *
499	     * @param telephone the raw telephone from the request payload
500	     * @return the E.164 string (e.g. {@code +61412345678})
501	     */
502	    private String normalizeTelephone(String telephone) {
503	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
504	        String candidate;
505	        if (cleaned.startsWith("+")) {
506	            candidate = cleaned;
507	        } else {
508	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
509	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
510	        }
511	        if (!E164_PATTERN.matcher(candidate).matches()) {
512	            throw new InvalidRequestException(List.of("telephone"));
513	        }
514	        return candidate;
515	    }
516	
517	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
518	    @Transactional
519	    @Override
520	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
521	        Owner owner = this.clinicService.findOwnerById(ownerId);
522	        if (owner == null) {
523	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
524	        }
525	        this.clinicService.deleteOwner(owner);
526	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
527	    }
