529	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
530	    @Override
531	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
532	        Owner owner = this.clinicService.findOwnerById(ownerId);
533	        if (owner == null) {
534	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	        }
536	        HttpHeaders headers = new HttpHeaders();
537	        Pet pet = petMapper.toPet(petFieldsDto);
538	        owner.setId(ownerId);
539	        pet.setOwner(owner);
540	        pet.getType().setName(null);
541	        this.clinicService.savePet(pet);
542	        PetDto petDto = petMapper.toPetDto(pet);
543	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
544	            .buildAndExpand(pet.getId()).toUri());
545	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
546	    }
547	
548	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
549	    @Override
550	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
551	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
552	        if (currentOwner != null) {
553	            Pet currentPet = this.clinicService.findPetById(petId);
554	            if (currentPet != null) {
555	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
556	                currentPet.setName(petFieldsDto.getName());
557	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
558	                this.clinicService.savePet(currentPet);
559	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
560	            }
561	        }
562	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
563	    }
