568	        HttpHeaders headers = new HttpHeaders();
569	        Visit visit = visitMapper.toVisit(visitFieldsDto);
570	        Pet pet = new Pet();
571	        pet.setId(petId);
572	        visit.setPet(pet);
573	        this.clinicService.saveVisit(visit);
574	        VisitDto visitDto = visitMapper.toVisitDto(visit);
